  maxLife: number;
}

function powerUpEffectColor(type: PowerUpType): number {
  switch (type) {
    case 'shield': return 0x4488ff;
    case 'scoreboost': return 0xffcc00;
    case 'freeze': return 0x88ffff;
  }
}

export class EffectsSystem extends createSystem({}) {
  private particleGroup!: Group;
  private particles: Particle[] = [];
  private ambientOrbs: Mesh[] = [];

  init() {
    this.particleGroup = new Group();
    this.scene.add(this.particleGroup);
    onEffectEvent((evt: EffectEvent) => this.handleEffect(evt));
    this.createAmbientOrbs();
  }

  private createAmbientOrbs() {
    const cs = COLOR_SCHEMES[state.colorScheme];
    // More orbs at higher rounds
    const orbCount = 15 + Math.min(state.round, 10) * 2;
    // Clean up old orbs
    for (const orb of this.ambientOrbs) {
      this.scene.remove(orb);
    }
    this.ambientOrbs = [];

    for (let i = 0; i < orbCount; i++) {
      const geo = new SphereGeometry(0.05 + Math.random() * 0.05, 6, 6);
      const mat = new MeshBasicMaterial({
        color: new Color(cs.accent),
        transparent: true,
        opacity: 0.4,
        blending: AdditiveBlending,
      });
      const orb = new Mesh(geo, mat);
      orb.position.set(
        (Math.random() - 0.5) * 8,
        Math.random() * 6,
        (Math.random() - 0.5) * 8
      );
      this.scene.add(orb);
      this.ambientOrbs.push(orb);
    }
  }

  private spawnParticles(x: number, y: number, z: number, count: number, color: number, speed: number) {
    for (let i = 0; i < count; i++) {
      const geo = new SphereGeometry(0.03, 4, 4);
      const mat = new MeshBasicMaterial({
        color: new Color(color),
        transparent: true,
        opacity: 1,
        blending: AdditiveBlending,
      });
      const mesh = new Mesh(geo, mat);
      mesh.position.set(x, y, z);
      this.particleGroup.add(mesh);

      const angle = Math.random() * Math.PI * 2;
      const upAngle = Math.random() * Math.PI * 0.5;
      const vel = new Vector3(
        Math.cos(angle) * Math.cos(upAngle) * speed,
        Math.sin(upAngle) * speed + Math.random() * speed * 0.5,
        Math.sin(angle) * Math.cos(upAngle) * speed
      );

      this.particles.push({
        mesh,
        velocity: vel,
        life: 0.5 + Math.random() * 0.5,
        maxLife: 0.5 + Math.random() * 0.5,
      });
    }
  }

  private spawnTrailParticle(x: number, y: number, z: number) {
    const cs = COLOR_SCHEMES[state.colorScheme];
    const geo = new SphereGeometry(0.025, 4, 4);
    const mat = new MeshBasicMaterial({
      color: new Color(cs.target),
      transparent: true,
      opacity: 0.7,
      blending: AdditiveBlending,
    });
    const mesh = new Mesh(geo, mat);
    mesh.position.set(x, y, z);
    this.particleGroup.add(mesh);

    // Trail particles drift slowly downward and fade
    const vel = new Vector3(
      (Math.random() - 0.5) * 0.2,
      -0.3 - Math.random() * 0.2,
      (Math.random() - 0.5) * 0.2
    );

    this.particles.push({
      mesh,
      velocity: vel,
      life: 0.4,
      maxLife: 0.4,
    });
  }

  private spawnRingBurst(x: number, y: number, z: number, count: number, color: number, radius: number) {
    for (let i = 0; i < count; i++) {
      const angle = (i / count) * Math.PI * 2;
      const geo = new SphereGeometry(0.04, 4, 4);
      const mat = new MeshBasicMaterial({
        color: new Color(color),
        transparent: true,
        opacity: 1,
        blending: AdditiveBlending,
      });
      const mesh = new Mesh(geo, mat);
      mesh.position.set(x, y, z);
      this.particleGroup.add(mesh);

      const vel = new Vector3(
        Math.cos(angle) * radius * 3,
        0.5 + Math.random() * 0.5,
        Math.sin(angle) * radius * 3
      );

      this.particles.push({
        mesh,
        velocity: vel,
        life: 0.8,
        maxLife: 0.8,
      });
    }
  }

  private spawnScorePopup(x: number, y: number, z: number) {
    // Cluster of golden particles that float upward to represent score gain
    for (let i = 0; i < 5; i++) {
      const geo = new SphereGeometry(0.04 + i * 0.008, 6, 6);
      const mat = new MeshBasicMaterial({
        color: new Color(0xffdd44),
        transparent: true,
        opacity: 1,
        blending: AdditiveBlending,
      });
      const mesh = new Mesh(geo, mat);
      mesh.position.set(x + (Math.random() - 0.5) * 0.15, y + i * 0.06, z);
      this.particleGroup.add(mesh);

      const vel = new Vector3(
        (Math.random() - 0.5) * 0.3,
        1.5 + Math.random() * 0.5,
        (Math.random() - 0.5) * 0.2
      );

      this.particles.push({
        mesh,
        velocity: vel,
        life: 1.0,
        maxLife: 1.0,
      });
    }
  }

  private handleEffect(evt: EffectEvent) {
    const cs = COLOR_SCHEMES[state.colorScheme];
    switch (evt.type) {
      case 'hop_land':
        this.spawnParticles(evt.x, evt.y, evt.z, 8, cs.target, 1);
        break;
      case 'death':
        this.spawnParticles(evt.x, evt.y, evt.z, 25, 0xff0000, 2.5);
        // Additional red ring burst on death
        this.spawnRingBurst(evt.x, evt.y, evt.z, 12, 0xff4400, 0.5);
        break;
      case 'round_complete':
        for (let r = 0; r < PYRAMID_ROWS; r++) {
          for (let c = 0; c <= r; c++) {
            const pos = cubePos(r, c);
            this.spawnParticles(pos.x, pos.y + 0.3, pos.z, 3, cs.target, 1.5);
          }
        }
        break;
      case 'enemy_die':
        this.spawnParticles(evt.x, evt.y, evt.z, 12, 0xaa00ff, 1.5);
        break;
      case 'powerup_collect':
        {
          const color = powerUpEffectColor(evt.powerUpType);
          // Big burst + ring
          this.spawnParticles(evt.x, evt.y, evt.z, 20, color, 2);
          this.spawnRingBurst(evt.x, evt.y, evt.z, 16, color, 0.6);
        }
        break;
      case 'combo':
        {
          // Golden upward burst, bigger with higher combos
          const count = Math.min(evt.combo * 4, 24);
          this.spawnParticles(evt.x, evt.y, evt.z, count, 0xffcc00, 1 + evt.combo * 0.3);
        }
        break;
      case 'hop_trail':
        // Small glowing trail particle
        this.spawnTrailParticle(evt.x, evt.y, evt.z);
        break;
      case 'round_wave':
        // Golden upward fountain per cube
        this.spawnParticles(evt.x, evt.y, evt.z, 6, 0xffcc00, 1.2);
        break;
      case 'score_popup':
        // Score popup: rising golden glow particles in a cluster to indicate points gained
        this.spawnScorePopup(evt.x, evt.y, evt.z);
        break;
    }
  }

  update(delta: number, time: number) {
    // Update particles
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= delta;
      if (p.life <= 0) {
        this.particleGroup.remove(p.mesh);
        this.particles.splice(i, 1);
        continue;
      }
      p.velocity.y -= delta * 2; // gravity
      p.mesh.position.add(p.velocity.clone().multiplyScalar(delta));
      const mat = p.mesh.material as MeshBasicMaterial;
      mat.opacity = p.life / p.maxLife;
    }

    // Animate ambient orbs
    const cs = COLOR_SCHEMES[state.colorScheme];
    for (let i = 0; i < this.ambientOrbs.length; i++) {
      const orb = this.ambientOrbs[i];
      const offset = i * 0.7;
      // Faster movement at higher rounds
      const speedMult = 1 + Math.min(state.round, 10) * 0.1;
      orb.position.y += Math.sin(time * 0.5 * speedMult + offset) * delta * 0.3;
      orb.position.x += Math.cos(time * 0.3 * speedMult + offset) * delta * 0.1;
      // Wrap around
      if (orb.position.y > 7) orb.position.y = -1;
      if (orb.position.y < -1) orb.position.y = 7;
      const mat = orb.material as MeshBasicMaterial;
      mat.color.setHex(cs.accent);
      mat.opacity = 0.2 + Math.sin(time + offset) * 0.15;
    }

    // Limit total particles to avoid performance issues
    if (this.particles.length > 200) {
      const excess = this.particles.length - 200;
      for (let i = 0; i < excess; i++) {
        const p = this.particles[0];
        this.particleGroup.remove(p.mesh);
        this.particles.shift();
      }
    }
  }
}

import {
  createSystem,
  Group,
  Mesh,
  BoxGeometry,
  CylinderGeometry,
  SphereGeometry,
  MeshStandardMaterial,
  MeshBasicMaterial,
  Color,
  AmbientLight,
  PointLight,
  DirectionalLight,
  AdditiveBlending,
  FogExp2,
} from '@iwsdk/core';
import { COLOR_SCHEMES, state } from './game-state';

export class EnvironmentSystem extends createSystem({}) {
  private envGroup!: Group;
  private floorMesh!: Mesh;
  private pillars: Mesh[] = [];
  private ceilingLights: PointLight[] = [];
  private glowPool!: Mesh;
  private pillarCaps: Mesh[] = [];
  private stars: Mesh[] = [];

  init() {
    this.envGroup = new Group();
    this.scene.add(this.envGroup);

    // Fog for depth
    this.scene.fog = new FogExp2(0x000811, 0.04);

    // Ambient light
    const ambient = new AmbientLight(0x112244, 0.5);
    this.scene.add(ambient);

    // Main directional light
    const dirLight = new DirectionalLight(0x4488cc, 0.8);
    dirLight.position.set(5, 10, 5);
    this.scene.add(dirLight);

    this.createFloor();
    this.createPillars();
    this.createCeilingLights();
    this.createGlowPool();
    this.createStarfield();
  }

  private createFloor() {
    // Grid floor using wireframe box
    const floorGeo = new BoxGeometry(30, 0.01, 30);
    const floorMat = new MeshBasicMaterial({
      color: new Color(0x112233),
      transparent: true,
      opacity: 0.6,
      wireframe: true,
    });
    this.floorMesh = new Mesh(floorGeo, floorMat);
    this.floorMesh.position.set(0, -0.5, 0);
    this.envGroup.add(this.floorMesh);

    // Solid dark floor underneath
    const solidGeo = new BoxGeometry(30, 0.005, 30);
    const solidMat = new MeshStandardMaterial({
      color: new Color(0x050510),
      transparent: true,
      opacity: 0.9,
    });
    const solidFloor = new Mesh(solidGeo, solidMat);
    solidFloor.position.set(0, -0.52, 0);
    this.envGroup.add(solidFloor);
  }

  private createPillars() {
    const cs = COLOR_SCHEMES[state.colorScheme];
    const positions = [
      [-6, 0, -6], [6, 0, -6], [-6, 0, 6], [6, 0, 6],
      [-3, 0, -8], [3, 0, -8], [-8, 0, 0], [8, 0, 0],
    ];

    for (const pos of positions) {
      // Pillar body - wireframe cylinder
      const geo = new CylinderGeometry(0.15, 0.15, 10, 6);
      const mat = new MeshBasicMaterial({
        color: new Color(cs.accent),
        transparent: true,
        opacity: 0.15,
        wireframe: true,
      });
      const pillar = new Mesh(geo, mat);
      pillar.position.set(pos[0], 4.5, pos[2]);
      this.envGroup.add(pillar);
      this.pillars.push(pillar);

      // Pillar cap - small glowing sphere
      const capGeo = new SphereGeometry(0.2, 8, 8);
      const capMat = new MeshBasicMaterial({
        color: new Color(cs.accent),
        transparent: true,
        opacity: 0.5,
        blending: AdditiveBlending,
      });
      const cap = new Mesh(capGeo, capMat);
      cap.position.set(pos[0], 9.5, pos[2]);
      this.envGroup.add(cap);
      this.pillarCaps.push(cap);
    }
  }

  private createCeilingLights() {
    const cs = COLOR_SCHEMES[state.colorScheme];
    const positions = [
      [0, 9, 0], [-4, 9, -4], [4, 9, -4], [-4, 9, 4], [4, 9, 4],
    ];

    for (const pos of positions) {
      const light = new PointLight(cs.accent, 0.5, 15);
      light.position.set(pos[0], pos[1], pos[2]);
      this.scene.add(light);
      this.ceilingLights.push(light);
    }
  }

  private createGlowPool() {
    // Floor glow pool under the pyramid
    const geo = new BoxGeometry(5, 0.005, 5);
    const mat = new MeshBasicMaterial({
      color: new Color(COLOR_SCHEMES[state.colorScheme].accent),
      transparent: true,
      opacity: 0.15,
      blending: AdditiveBlending,
    });
    this.glowPool = new Mesh(geo, mat);
    this.glowPool.position.set(0, -0.45, 1.5);
    this.envGroup.add(this.glowPool);
  }

  private createStarfield() {
    const starCount = 60;
    for (let i = 0; i < starCount; i++) {
      const size = 0.02 + Math.random() * 0.04;
      const geo = new SphereGeometry(size, 4, 4);
      const brightness = 0.3 + Math.random() * 0.7;
      const colorHex = brightness > 0.6 ? 0xccddff : 0x8899bb;
      const mat = new MeshBasicMaterial({
        color: new Color(colorHex),
        transparent: true,
        opacity: 0.3 + Math.random() * 0.5,
        blending: AdditiveBlending,
      });
      const star = new Mesh(geo, mat);
      // Distribute stars in a dome-like hemisphere above the play area
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.random() * Math.PI * 0.45; // upper hemisphere
      const r = 12 + Math.random() * 8;
      star.position.set(
        Math.cos(theta) * Math.sin(phi) * r,
        8 + Math.cos(phi) * r * 0.5,
        Math.sin(theta) * Math.sin(phi) * r
      );
      this.envGroup.add(star);
      this.stars.push(star);
    }
  }

  update(_delta: number, time: number) {
    const cs = COLOR_SCHEMES[state.colorScheme];

    // Pulse ceiling lights
    for (let i = 0; i < this.ceilingLights.length; i++) {
      const light = this.ceilingLights[i];
      light.intensity = 0.3 + Math.sin(time * 0.5 + i * 1.2) * 0.15;
      light.color.setHex(cs.accent);
    }

    // Pulse glow pool
    const poolMat = this.glowPool.material as MeshBasicMaterial;
    poolMat.opacity = 0.1 + Math.sin(time * 0.8) * 0.05;
    poolMat.color.setHex(cs.accent);

    // Update pillar colors
    for (const pillar of this.pillars) {
      (pillar.material as MeshBasicMaterial).color.setHex(cs.accent);
    }
    for (const cap of this.pillarCaps) {
      const capMat = cap.material as MeshBasicMaterial;
      capMat.color.setHex(cs.accent);
      capMat.opacity = 0.3 + Math.sin(time * 1.5) * 0.2;
    }

    // Subtle floor grid color update
    (this.floorMesh.material as MeshBasicMaterial).color.setHex(
      (cs.accent & 0xfefefe) >> 2
    );

    // Animate starfield - gentle twinkle
    for (let i = 0; i < this.stars.length; i++) {
      const star = this.stars[i];
      const mat = star.material as MeshBasicMaterial;
      const phase = i * 1.7 + time * (0.3 + (i % 5) * 0.1);
      mat.opacity = 0.15 + Math.sin(phase) * 0.25 + Math.sin(phase * 2.3) * 0.1;
      // Very slow drift
      star.position.y += Math.sin(time * 0.1 + i) * _delta * 0.02;
    }
  }
}

import {
  createSystem,
  Group,
  Mesh,
  BoxGeometry,
  SphereGeometry,
  MeshStandardMaterial,
  MeshBasicMaterial,
  Color,
  AdditiveBlending,
} from '@iwsdk/core';
import { state, cubePos, PYRAMID_ROWS, CUBE_SIZE, PILLAR_HEIGHT, COLOR_SCHEMES } from './game-state';

// Render system handles visual effects: cube edge glow, ambient cube pulsing
export class RenderSystem extends createSystem({}) {
  private edgeGroup!: Group;
  private edgeMeshes: Mesh[] = [];
  private glowTime = 0;

  init() {
    this.edgeGroup = new Group();
    this.scene.add(this.edgeGroup);
    this.buildEdges();
  }

  private buildEdges() {
    // Remove old
    for (const m of this.edgeMeshes) this.edgeGroup.remove(m);
    this.edgeMeshes = [];

    const cs = COLOR_SCHEMES[state.colorScheme];
    for (let r = 0; r < PYRAMID_ROWS; r++) {
      for (let c = 0; c <= r; c++) {
        const pos = cubePos(r, c);
        // Wireframe outline using thin boxes for edges (neon glow effect)
        const edgeSize = CUBE_SIZE + 0.02;
        const geo = new BoxGeometry(edgeSize, PILLAR_HEIGHT + 0.02, edgeSize);
        const mat = new MeshBasicMaterial({
          color: new Color(cs.accent),
          transparent: true,
          opacity: 0.3,
          wireframe: true,
        });
        const mesh = new Mesh(geo, mat);
        mesh.position.set(pos.x, pos.y, pos.z);
        this.edgeGroup.add(mesh);
        this.edgeMeshes.push(mesh);
      }
    }
  }

  update(delta: number, time: number) {
    this.glowTime = time;

    // Pulse edge glow
    const pulse = 0.2 + Math.sin(time * 2) * 0.1;
    const cs = COLOR_SCHEMES[state.colorScheme];

    for (let i = 0; i < this.edgeMeshes.length; i++) {
      const mesh = this.edgeMeshes[i];
      const mat = mesh.material as MeshBasicMaterial;
      mat.opacity = pulse;

      // Update edge color to match current scheme
      mat.color.setHex(cs.accent);

      // Position edges to match cubes (in case pyramid was rebuilt)
      if (i < state.cubes.length) {
        const cube = state.cubes[i];
        const pos = cubePos(cube.row, cube.col);
        mesh.position.set(pos.x, pos.y, pos.z);
      }
    }

    // Rebuild edges if count changed
    if (this.edgeMeshes.length !== state.cubes.length) {
      this.buildEdges();
    }
  }
}

import { createSystem, InputComponent } from '@iwsdk/core';
import { state } from './game-state';
import { GameSystem } from './game-system';

export class InputSystem extends createSystem({}) {
  private gameSystem!: GameSystem;
  private inputCooldown = 0;

  init() {
    const gs = this.world.getSystem(GameSystem);
    if (gs) this.gameSystem = gs;
  }

  update(delta: number, _time: number) {
    if (this.inputCooldown > 0) {
      this.inputCooldown -= delta;
      return;
    }

    if (state.screen === 'playing' && !state.hopping && !state.deathAnimating && !state.roundComplete) {
      this.handlePlayInput();
    }

    if (state.screen === 'playing') {
      this.handlePauseInput();
    }
  }

  private handlePlayInput() {
    const kb = this.input.keyboard;

    // Keyboard: Q/ArrowUp+ArrowLeft = up-left, E/ArrowUp+ArrowRight = up-right
    // A/ArrowDown+ArrowLeft = down-left, D/ArrowDown+ArrowRight = down-right
    let dr = 0;
    let dc = 0;

    if (kb.getKeyDown('KeyQ') || kb.getKeyDown('Numpad7')) {
      dr = -1; dc = -1;
    } else if (kb.getKeyDown('KeyE') || kb.getKeyDown('Numpad9')) {
      dr = -1; dc = 0;
    } else if (kb.getKeyDown('KeyA') || kb.getKeyDown('Numpad1')) {
      dr = 1; dc = 0;
    } else if (kb.getKeyDown('KeyD') || kb.getKeyDown('Numpad3')) {
      dr = 1; dc = 1;
    } else if (kb.getKeyDown('ArrowUp') && kb.getKeyPressed('ArrowLeft')) {
      dr = -1; dc = -1;
    } else if (kb.getKeyDown('ArrowUp') && kb.getKeyPressed('ArrowRight')) {
      dr = -1; dc = 0;
    } else if (kb.getKeyDown('ArrowDown') && kb.getKeyPressed('ArrowLeft')) {
      dr = 1; dc = 0;
    } else if (kb.getKeyDown('ArrowDown') && kb.getKeyPressed('ArrowRight')) {
      dr = 1; dc = 1;
    } else if (kb.getKeyDown('ArrowUp')) {
      dr = -1; dc = 0; // Default up = up-right
    } else if (kb.getKeyDown('ArrowDown')) {
      dr = 1; dc = 0; // Default down = down-left
    } else if (kb.getKeyDown('ArrowLeft')) {
      dr = -1; dc = -1; // left = up-left
    } else if (kb.getKeyDown('ArrowRight')) {
      dr = 1; dc = 1; // right = down-right
    }

    // VR Controller input
    const right = this.input.xr.gamepads.right;
    if (right) {
      const stick = right.getAxesValues(InputComponent.Thumbstick);
      if (stick && (Math.abs(stick.x) > 0.5 || Math.abs(stick.y) > 0.5)) {
        // Map thumbstick to isometric directions
        if (stick.y < -0.5 && stick.x < -0.3) {
          dr = -1; dc = -1; // up-left
        } else if (stick.y < -0.5 && stick.x > 0.3) {
          dr = -1; dc = 0; // up-right
        } else if (stick.y > 0.5 && stick.x < -0.3) {
          dr = 1; dc = 0; // down-left
        } else if (stick.y > 0.5 && stick.x > 0.3) {
          dr = 1; dc = 1; // down-right
        } else if (stick.y < -0.5) {
          dr = -1; dc = 0;
        } else if (stick.y > 0.5) {
          dr = 1; dc = 1;
        } else if (stick.x < -0.5) {
          dr = -1; dc = -1;
        } else if (stick.x > 0.5) {
          dr = 1; dc = 1;
        }
        this.inputCooldown = 0.3;
      }
    }

    if (dr !== 0 || dc !== 0) {
      state.pendingInput = { dr, dc };
      this.inputCooldown = 0.15;
    }
  }

  private handlePauseInput() {
    const kb = this.input.keyboard;
    if (kb.getKeyDown('Escape') || kb.getKeyDown('KeyP')) {
      if (state.screen === 'playing') {
        state.screen = 'paused';
      }
    }

    // VR B button for pause
    const right = this.input.xr.gamepads.right;
    if (right && right.getButtonDown(InputComponent.B_Button)) {
      if (state.screen === 'playing') {
        state.screen = 'paused';
      }
    }
  }
}

import { World } from '@iwsdk/core';
import { GameSystem } from './game-system';
import { RenderSystem } from './render-system';
import { InputSystem } from './input-system';
import { UISystem } from './ui-system';
import { AudioSystem } from './audio-system';
import { EffectsSystem } from './effects-system';
import { EnvironmentSystem } from './environment-system';

async function main() {
  const container = document.getElementById('scene-container') as HTMLDivElement;
  const world = await World.create(container, {
    xr: { offer: 'once' },
    render: {
      near: 0.1,
      far: 200,
      camera: { position: [2, 5.5, 5], lookAt: [0, 1.2, 1.2] },
    },
    input: { canvasPointerEvents: true },
    features: {
      locomotion: false,
    },
  });

  world.registerSystem(EnvironmentSystem);
  world.registerSystem(GameSystem);
  world.registerSystem(RenderSystem);
  world.registerSystem(InputSystem);
  world.registerSystem(AudioSystem);
  world.registerSystem(EffectsSystem);
  world.registerSystem(UISystem);
}

main().catch(console.error);

